+    const fullNameInput = document.getElementById('fullName');
+    const emailInput = document.getElementById('email');
+    const phoneInput = document.getElementById('phone');
+    const successMessage = document.getElementById('formSuccess');
+
+    const validators = {
+        fullName: (value) => {
+            if (!value.trim()) return 'Full name is required.';
+            if (value.trim().length < 2) return 'Full name must be at least 2 characters.';
+            return '';
+        },
+        email: (value) => {
+            if (!value.trim()) return 'Email address is required.';
+            const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+            if (!emailRegex.test(value)) return 'Please enter a valid email address.';
+            return '';
+        },
+        phone: (value) => {
+            if (!value.trim()) return ''; // Optional
+            const phoneRegex = /^\d{3}-\d{3}-\d{4}$/;
+            if (!phoneRegex.test(value)) return 'Please use the format 123-456-7890.';
+            return '';
+        }
+    };
+
+    const validateField = (input, validator) => {
+        const errorElement = document.getElementById(`${input.id}Error`);
+        const errorMessage = validator(input.value);
+        
+        if (errorMessage) {
+            input.classList.add('invalid');
+            errorElement.textContent = errorMessage;
+            return false;
+        } else {
+            input.classList.remove('invalid');
+            errorElement.textContent = '';
+            return true;
+        }
+    };
+
+    // Inline validation on blur and input
+    fullNameInput.addEventListener('blur', () => validateField(fullNameInput, validators.fullName));
+    fullNameInput.addEventListener('input', () => {
+        if (fullNameInput.classList.contains('invalid')) {
+            validateField(fullNameInput, validators.fullName);
+        }
+    });
+
+    emailInput.addEventListener('blur', () => validateField(emailInput, validators.email));
+    emailInput.addEventListener('input', () => {
+        if (emailInput.classList.contains('invalid')) {
+            validateField(emailInput, validators.email);
+        }
+    });
+
+    phoneInput.addEventListener('blur', () => validateField(phoneInput, validators.phone));
+    phoneInput.addEventListener('input', () => {
+        if (phoneInput.classList.contains('invalid')) {
+            validateField(phoneInput, validators.phone);
+        }
+    });
+
+    form.addEventListener('submit', (e) => {
+        e.preventDefault();
+
+        const isFullNameValid = validateField(fullNameInput, validators.fullName);
+        const isEmailValid = validateField(emailInput, validators.email);
+        const isPhoneValid = validateField(phoneInput, validators.phone);
+
+        if (isFullNameValid && isEmailValid && isPhoneValid) {
+            // Form is valid
+            console.log('Form submitted:', {
+                fullName: fullNameInput.value,
+                email: emailInput.value,
+                phone: phoneInput.value
+            });
+
+            // Simulate success
+            form.style.display = 'none';
+            successMessage.style.display = 'block';
+        }
+    });
+});
+
")
